isOpen.example:
// client
if (kcds.world.WorldMap.isOpen) {
  kcds.ui.Hud.showNotification('Close the map to fight.');
}

isOpen.exampleCs:
// client
if (WorldMap.IsOpen)
{
    Hud.ShowNotification("Close the map to fight.");
}

getWaypoint.example:
// client
const waypoint = kcds.world.WorldMap.getWaypoint();
if (waypoint) {
  const { x, y } = waypoint.position;
  kcds.core.Events.toServer('party:waypoint', { x, y });
}

getWaypoint.exampleCs:
// client
var waypoint = WorldMap.GetWaypoint();
if (waypoint)
{
    var x = waypoint["position"]["x"];
    var y = waypoint["position"]["y"];
    Events.ToServer("party:waypoint", new { x = x, y = y });
}

shiftWaypoint.example:
// client
const { WorldMap } = kcds.world;

if (WorldMap.getWaypoint()) {
  WorldMap.shiftWaypoint(new kcds.math.Vector3(512, 830, 31));
}

clearAllFog.example:
// client
if (!kcds.world.WorldMap.clearAllFog()) {
  console.log('the level is not up yet');
}

clearAllFog.exampleCs:
// client
if (!WorldMap.ClearAllFog())
{
    Log.Info("the level is not up yet");
}

clearFog.example:
// client: where this character has been, as your resource stored it
for (const place of visited) {
  kcds.world.WorldMap.clearFog(place);
}

clearFog.exampleCs:
// client: where this character has been, as your resource stored it
foreach (var place in visited)
{
    WorldMap.ClearFog(place);
}

discover.example:
// client: the places this character found earlier
for (const place of character.places) {
  kcds.world.WorldMap.discover(place);
}

discover.exampleCs:
// client: the places this character found earlier
foreach (var place in character["places"])
{
    WorldMap.Discover(place);
}
